package com.ruoyi.medical.persistence;
import com.ruoyi.medical.identity.*;import com.ruoyi.medical.persistence.mapper.*;import javax.sql.DataSource;import org.springframework.context.annotation.*;import org.springframework.boot.autoconfigure.condition.ConditionalOnExpression;import org.springframework.beans.factory.annotation.Value;import org.springframework.beans.factory.annotation.Qualifier;
/** Explicit disabled-by-default deployment. Required dependencies/configuration fail startup rather than create placeholders. */
@Configuration @ConditionalOnExpression("${medical.model-runtime.enabled:false} and ${medical.formal-invocation.enabled:false}")
public class FormalInvocationConfiguration {
 @Bean FormalInvocationHttpSchema formalInvocationHttpSchema(FormalInvocationSchema schema)throws Exception{return new FormalInvocationHttpSchema(schema);}
 @Bean(name="formalInvocationObjectTransport") RuntimeObjectTransport formalInvocationObjectTransport(SourceUploadTransport deployed,@Value("${medical.formal-invocation.object-directory}")String directory,@Value("${medical.formal-invocation.maximum-result-bytes}")int maximum)throws Exception{bounds(maximum);return new RuntimeObjectTransport(deployed,java.nio.file.Path.of(directory),maximum);}
 @Bean FormalInvocationSchema formalInvocationSchema()throws Exception{return new FormalInvocationSchema();}
 @Bean FormalVerificationJobs formalVerificationJobs(DataSource d,PermissionSchema j,FormalInvocationSchema s,RunTokenAuthoritySchema r){return new FormalVerificationJobs(d,j,s,r);}
 @Bean FormalModelVerificationBootstrap formalModelVerificationBootstrap(FormalVerificationJobs j,FormalCapabilityIdentityAuthority c,PermissionMapper p,PermissionAuthority a,FormalInvocationSchema s,RunTokenAuthoritySchema r,DataSource d){return new FormalModelVerificationBootstrap(j,c,p,a,s,r,d);}
 @Bean FormalInvocationRules formalInvocationRules(RuleVersionMapper r,RuleVersionSchema s,PermissionSchema j,AgentPublicationDependencies d,ResourceReadAuthority a,DataSource db){return new FormalInvocationRules(r,s,j,d,a,db);}
 @Bean FormalInvocationInputs formalInvocationInputs(EnterpriseAccess a,DocumentReadMapper d,ScopeSnapshotSchema s,ArtifactRegistryMapper r,ArtifactSourceAuthority o,DependencyLineage l,SourceUploadTransport t,PermissionSchema j,DocumentUploadPolicy p)throws Exception{p.requireConfigured();return new FormalInvocationInputs(a,d,s,r,o,l,t,j,p);}
 @Bean FormalInvocationSourceOriginals formalInvocationSourceOriginals(EnterpriseAccess a,SourceReadAuthority s,SourceReadMapper rows,VersionResourceAuthority v,DependencyLineage l,SourceUploadTransport t,DataSource d,DocumentUploadPolicy p,@Value("${medical.formal-invocation.maximum-input-bytes}")int maximum){bounds(maximum);p.requireConfigured();return new FormalInvocationSourceOriginals(a,s,rows,v,l,t,d,p.environment(),p.region(),maximum,p.limits());}
 @Bean FormalInvocationPriceAuthority formalInvocationPriceAuthority(EnterpriseAccess a,ModelConfigurationService m,FormalInvocationSourceOriginals o,FormalInvocationSchema s,@Value("${medical.formal-invocation.maximum-input-bytes}")int maximum){bounds(maximum);return new FormalInvocationPriceAuthority(a,m,o,s,maximum);}
 @Bean FormalTokenizerRunner formalTokenizerRunner(@Value("${medical.formal-invocation.tokenizer-executable}")String executable,@Value("${medical.formal-invocation.tokenizer-sha256}")String hash,@Value("${medical.formal-invocation.tokenizer-version}")String version,@Value("${medical.formal-invocation.maximum-input-bytes}")int maximum,@Value("${medical.formal-invocation.tokenizer-output-bytes}")int output,@Value("${medical.formal-invocation.tokenizer-timeout-ms}")long timeout){bounds(maximum);return new FormalTokenizerRunner(new FormalTokenizerRunner.Configuration(true,java.nio.file.Path.of(executable),hash,version,maximum,output,java.time.Duration.ofMillis(timeout)));}
 @Bean FormalVerificationPreparation formalVerificationPreparation(EnterpriseAccess a,ModelConfigurationService m,ResourceReadAuthority r,FormalCapabilityIdentityAuthority c,FormalInvocationRules rules,FormalInvocationInputs i,FormalInvocationPriceAuthority p,FormalInvocationSourceOriginals o,FormalTokenizerRunner t,FormalInvocationSchema s,RunTokenAuthoritySchema rs,PermissionSchema j,@Value("${medical.formal-invocation.service-uri}")String service,@Value("${medical.formal-invocation.audience}")String audience){return new FormalVerificationPreparation(a,m,r,c,rules,i,p,o,t,s,rs,j,service,audience);}
 @Bean FormalInvocationCurrent formalInvocationCurrent(ModelConfigurationService m,FormalCapabilityIdentityAuthority c,FormalInvocationRules r,FormalInvocationInputs i,FormalInvocationSourceOriginals o,ResourceReadAuthority a,ApprovedCredentialAuthority credentials,FormalInvocationSchema s,DataSource d){return new FormalInvocationCurrent(m,c,r,i,o,a,credentials,s,d);}
 @Bean FormalInvocationStarts formalInvocationStarts(EnterpriseAccess a,FormalVerificationPreparation p,FormalVerificationJobs j,FormalInvocationCurrent c,DataSource d){return new FormalInvocationStarts(a,p,j,c,d);}
 @Bean FormalInvocationBudget formalInvocationBudget(RunCreateBudget r,BudgetSchema b,PermissionSchema j,DataSource d){return new FormalInvocationBudget(r,b,j,d);}
 @Bean FormalInvocationReservations formalInvocationReservations(FormalVerificationJobs j,FormalInvocationCurrent c,FormalInvocationBudget b,FormalInvocationSchema s,DataSource d){return new FormalInvocationReservations(j,c,b,s,d);}
 @Bean FormalInvocationSendPreparation formalInvocationSendPreparation(FormalWorkerAccess w,FormalVerificationJobs j,FormalInvocationCurrent c,FormalInvocationInputs i,FormalInvocationSchema s,@Value("${medical.formal-invocation.maximum-input-bytes}")int maximum){bounds(maximum);return new FormalInvocationSendPreparation(w,j,c,i,s,maximum);}
 @Bean FormalInvocationDispatch formalInvocationDispatch(DataSource d,ServiceCertificateIdentity services,FormalInvocationSchema s,@Value("${medical.formal-invocation.maximum-send-seconds}")long seconds){return new FormalInvocationDispatch(d,services,s,seconds);}
 @Bean FormalInvocationOutcomeAuthority formalInvocationOutcomeAuthority(ServiceCertificateIdentity services,TenantTransaction t,DataSource d,FormalInvocationSchema s,@Value("${medical.formal-invocation.maximum-result-bytes}")int maximum)throws Exception{bounds(maximum);return new FormalInvocationOutcomeAuthority(services,t,d,s,maximum);}
 @Bean FormalProviderCaptureEvidence formalProviderCaptureEvidence(FormalInvocationSchema s,@Value("${medical.formal-invocation.maximum-result-bytes}")int maximum,@Value("${medical.formal-invocation.maximum-raw-response-bytes}")int raw)throws Exception{bounds(maximum);return new FormalProviderCaptureEvidence(s,maximum,raw);}
 @Bean FormalInvocationObjectLedger formalInvocationObjectLedger(DataSource d,FormalInvocationSchema s,@Value("${medical.formal-invocation.maximum-result-bytes}")int maximum){bounds(maximum);return new FormalInvocationObjectLedger(d,s,maximum);}
 @Bean FormalInvocationObjectRegistration formalInvocationObjectRegistration(DataSource d,FormalInvocationSchema s,FormalVerificationJobs j,DependencyManifestSchema ds,org.springframework.beans.factory.ObjectProvider<TaskInvocationRecords> tasks,org.springframework.beans.factory.ObjectProvider<TaskPlanDraftInvocationRecords> plans,org.springframework.beans.factory.ObjectProvider<TaskSectionWriterInvocationRecords> writers,org.springframework.beans.factory.ObjectProvider<TaskSourceVerifierInvocationRecords> verifiers,org.springframework.beans.factory.ObjectProvider<DocumentReviewInvocationRecords> documents){var n07=documents.getIfAvailable();var n05=verifiers.getIfAvailable();var n04=writers.getIfAvailable();var n01=plans.getIfAvailable();if(n07!=null)return new FormalInvocationObjectRegistration(d,s,j,ds,tasks.getIfAvailable(),n01,n04,n05,n07);if(n05!=null)return new FormalInvocationObjectRegistration(d,s,j,ds,tasks.getIfAvailable(),n01,n04,n05);if(n04!=null)return new FormalInvocationObjectRegistration(d,s,j,ds,tasks.getIfAvailable(),n01,n04);return n01==null?new FormalInvocationObjectRegistration(d,s,j,ds,tasks.getIfAvailable()):new FormalInvocationObjectRegistration(d,s,j,ds,tasks.getIfAvailable(),n01);}
 @Bean FormalInvocationReceiptObjects formalInvocationReceiptObjects(FormalInvocationOutcomeAuthority o,FormalProviderCaptureEvidence c,FormalInvocationObjectLedger l,@Qualifier("formalInvocationObjectTransport")RuntimeObjectTransport t,FormalInvocationObjectRegistration r){return new FormalInvocationReceiptObjects(o,c,l,t,r);}
 @Bean FormalInvocationSettlement formalInvocationSettlement(DataSource d,FormalInvocationSchema s,FormalVerificationJobs j,FormalInvocationObjectRegistration o,FormalInvocationReservations r,org.springframework.beans.factory.ObjectProvider<TaskInvocationRecords> tasks,org.springframework.beans.factory.ObjectProvider<TaskPlanDraftInvocationRecords> plans,org.springframework.beans.factory.ObjectProvider<TaskSectionWriterInvocationRecords> writers,org.springframework.beans.factory.ObjectProvider<TaskSourceVerifierInvocationRecords> verifiers,org.springframework.beans.factory.ObjectProvider<DocumentReviewInvocationRecords> documents){var n07=documents.getIfAvailable();var n05=verifiers.getIfAvailable();var n04=writers.getIfAvailable();var n01=plans.getIfAvailable();if(n07!=null)return new FormalInvocationSettlement(d,s,j,o,r,tasks.getIfAvailable(),n01,n04,n05,n07);if(n05!=null)return new FormalInvocationSettlement(d,s,j,o,r,tasks.getIfAvailable(),n01,n04,n05);if(n04!=null)return new FormalInvocationSettlement(d,s,j,o,r,tasks.getIfAvailable(),n01,n04);return n01==null?new FormalInvocationSettlement(d,s,j,o,r,tasks.getIfAvailable()):new FormalInvocationSettlement(d,s,j,o,r,tasks.getIfAvailable(),n01);}
 @Bean FormalInvocationCompleted formalInvocationCompleted(DataSource d,FormalVerificationJobs j,FormalInvocationCurrent c,FormalInvocationSettlement s,FormalInvocationObjectRegistration o,FormalProviderCaptureEvidence e,FormalInvocationSchema schema,ResourceReadAuthority r)throws Exception{return new FormalInvocationCompleted(d,j,c,s,o,e,schema,r);}
 @Bean FormalInvocationCancellation formalInvocationCancellation(DataSource d,FormalVerificationJobs j,FormalInvocationReservations r,ResourceReadAuthority a,FormalInvocationSchema s){return new FormalInvocationCancellation(d,j,r,a,s);}
 @Bean FormalInvocationService formalInvocationService(FormalInvocationStarts s,FormalInvocationCompleted c,FormalWorkerAccess w,FormalInvocationReservations r,FormalInvocationSendPreparation p,FormalInvocationDispatch d,FormalInvocationReceiptObjects o,FormalInvocationSettlement settlement){return new FormalInvocationService(s,c,w,r,p,d,o,settlement);}
 @Bean FormalInvocationUncertainty formalInvocationUncertainty(DataSource d,ServiceCertificateIdentity s,TenantTransaction t,FormalInvocationSchema j){return new FormalInvocationUncertainty(d,s,t,j);}
 @Bean FormalVerificationWorkerService formalVerificationWorkerService(DataSource d,ServiceCertificateIdentity s,TenantTransaction tx,RunTokenAuthority t,com.ruoyi.medical.identity.RunTokenPolicyStore p,FormalVerificationJobs j,FormalInvocationSchema json,RunTokenAuthoritySchema r,@Value("${medical.formal-invocation.worker-lease-seconds}")long seconds){return new FormalVerificationWorkerService(d,s,tx,t,p,j,json,r,seconds);}
 static void bounds(int bytes){if(bytes<1||bytes>16777216)throw new IllegalArgumentException("Explicit formal invocation byte bound must be within 1..16777216");}
}
